#include <iostream>
#include <iomanip>

int main() {
    int a = 171;
    int b = 32;
    double pi = 3.14159265;

    // Using manipulators with showbase, uppercase, and hex
    std::cout << std::showbase << std::uppercase << std::hex;
    std::cout << a << " " << b << "\n";

    // Reset back to decimal and test setw/setfill/showpos
    std::cout << std::dec << std::showpos;
    std::cout << std::setfill('*') << std::setw(8) << 42 << "\n";
    // setw resets to 0, but setfill and showpos remain sticky
    std::cout << 99 << "\n";

    // Floating-point precision
    std::cout << std::noshowpos << std::fixed << std::setprecision(2) << pi << "\n";

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    // We demonstrate stream buffering using an in-memory stringstream
    std::stringstream bufferStream;

    bufferStream << "Rect Area = " << (10 * 5) << '\n';
    bufferStream << "Rect Perimeter = " << (2 * (10 + 5));

    // Explicitly flush the stream buffer
    bufferStream.flush();

    // Also valid using manipulator syntax
    bufferStream << std::flush;

    std::cout << bufferStream.str() << "\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

// We demonstrate file stream semantics using stringstream simulation
// to ensure deterministic execution without host filesystem side effects.
int main() {
    // Simulating writing a sequence of 10 integers
    std::stringstream fileStream;
    int numbers[10] = {12, 45, 78, 23, 56, 89, 34, 67, 90, 11};

    for (int i = 0; i < 10; ++i) {
        fileStream << numbers[i] << ' ';
    }

    std::cout << "Written content: " << fileStream.str() << "\n";

    // Simulating reading the data back from the stream
    std::stringstream readStream(fileStream.str());
    int val;
    int count = 0;
    int sum = 0;
    while (readStream >> val) {
        sum += val;
        count++;
    }

    std::cout << "Count: " << count << ", Sum: " << sum << "\n";
    return 0;
}
